"use strict";
const path = require("node:path");
const { transformSync } = require("esbuild");

// Compact whitespace only. Classic globals, handler/function names, CSS order,
// property names and business expressions remain part of the existing API.
function compactBundle(output, content, inputMap) {
  const css = output.endsWith(".css"),
    mapName = path.posix.basename(output) + ".map",
    inlineMap = Buffer.from(inputMap).toString("base64"),
    mapped =
      content +
      (css
        ? "/*# sourceMappingURL=data:application/json;base64," +
          inlineMap +
          " */"
        : "//# sourceMappingURL=data:application/json;base64," + inlineMap);
  const result = transformSync(mapped, {
    loader: css ? "css" : "js",
    sourcefile: output,
    sourcemap: "external",
    sourcesContent: true,
    target: "esnext",
    charset: "utf8",
    minifyWhitespace: true,
    minifyIdentifiers: false,
    minifySyntax: false,
    treeShaking: false,
    legalComments: "inline",
    lineLimit: 160,
    banner: css
      ? "/* Generated by npm run build; edit src/styles. */"
      : "// Generated by npm run build. Edit src/ via source-map.json.",
  });
  if (result.warnings.length)
    throw Error(
      "Bundle compaction warning in " +
        output +
        ": " +
        result.warnings.map((warning) => warning.text).join("; "),
    );
  const map = JSON.parse(result.map);
  map.file = path.posix.basename(output);
  return {
    code:
      result.code +
      (css
        ? "/*# sourceMappingURL=" + mapName + " */\n"
        : "//# sourceMappingURL=" + mapName + "\n"),
    map: JSON.stringify(map) + "\n",
  };
}

module.exports = { compactBundle };
